mapper.select:
SELECT p.step_id, p.kind, p.answer_json, p.is_correct, p.score, p.rubric_json, p.feedback, p.graded_by, p.key_json FROM (SELECT DISTINCT ON (ua.step_id) ua.step_id, s.step_no, s.kind, ua.answer::text AS answer_json, ua.is_correct, ua.score::int AS score, ua.rubric::text AS rubric_json, ua.feedback, ua.graded_by, s.answer::text AS key_json FROM user_answers ua JOIN steps s ON s.id = ua.step_id WHERE ua.user_id = CAST(#{userId} AS uuid) AND ua.card_id = #{cardId}
AND (ua.created_at AT TIME ZONE 'Asia/Seoul')::date = #{date}
ORDER BY ua.step_id, ua.created_at DESC, ua.id DESC) p ORDER BY p.step_no
